content:
Here is a complete, idiomatic Terraform refactoring that consolidates duplicated `dev`/`prod` blocks into a single module driven by `for_each`. It includes the exact state migration steps required for a zero-diff transition.

### 1. Refactored Module (`modules/app_infra/main.tf`)

```hcl
variable "env_configs" {
  description = "Environment-specific configuration map"
  type = map(object({
    region             = string
    subnet_ids         = list(string)
    cluster_node_type  = string
    cluster_node_count = number
    rds_class          = string
    rds_multi_az       = bool
    enable_s3_repl     = bool
    repl_region        = string
    https_type         = string # "internal_alb" or "cloudfront"
    iam_mode           = string # "programmatic" or "oidc_role"
  }))
}

# --- S3 Bucket & Controls ---
resource "aws_s3_bucket" "assets" {
  for_each = var.env_configs
  bucket   = "myapp-assets-${each.value.region}-${each.key}"
  tags     = { Environment = each.key }
}

resource "aws_s3_bucket_versioning" "assets" {
  for_each = var.env_configs
  bucket   = aws_s3_bucket.assets[each.key].id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  for_each = var.env_configs
  bucket   = aws_s3_bucket.assets[each.key].id
  rule {
    apply_server_side_encryption_configuration { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  for_each = var.env_configs
  bucket   = aws_s3_bucket.assets[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Conditional: Prod-only cross-region replication
resource "aws_s3_bucket_replication_configuration" "assets" {
  for_each = { for k, v in var.env_configs : k => v if v.enable_s3_repl }
  bucket   = aws_s3_bucket.assets[each.key].id
  role     = aws_iam_role.s3_replication[each.key].arn

  rule {
    id     = "cross-region"
    status = "Enabled"
    destination {
      bucket = "arn:aws:s3:::myapp-assets-${each.value.repl_region}-${each.key}-replica"
    }
  }
}

# --- RDS PostgreSQL ---
resource "aws_db_instance" "app" {
  for_each            = var.env_configs
  identifier          = "myapp-db-${each.key}"
  engine              = "postgres"
  engine_version      = "15.4"
  instance_class      = each.value.rds_class
  allocated_storage   = 20
  db_name             = "myapp"
  username            = "admin"
  password            = aws_secretsmanager_secret_version.db_conn[each.key].secret_string
  skip_final_snapshot = true
  deletion_protection = true
  multi_az            = each.value.rds_multi_az
  storage_encrypted   = true
  backup_retention_period = 7
  publicly_accessible = false
}

# --- EKS Cluster & Node Group ---
resource "aws_eks_cluster" "app" {
  for_each = var.env_configs
  name     = "myapp-eks-${each.key}"
  role_arn = aws_iam_role.eks_cluster[each.key].arn
  vpc_config {
    subnet_ids = each.value.subnet_ids
  }
}

resource "aws_eks_node_group" "app" {
  for_each = var.env_configs
  cluster_name = aws_eks_cluster.app[each.key].name
  node_group_name = "myapp-ng-${each.key}"
  instance_types  = [each.value.cluster_node_type]
  scaling_config {
    desired_size = each.value.cluster_node_count
    max_size     = each.value.cluster_node_count
    min_size     = each.value.cluster_node_count
  }
  subnet_ids = each.value.subnet_ids
}

# --- HTTPS Exposure (ALB) ---
resource "aws_lb" "app" {
  for_each           = var.env_configs
  name               = "myapp-alb-${each.key}"
  internal           = each.value.https_type == "internal_alb"
  load_balancer_type = "application"
  subnets            = each.value.subnet_ids
}

resource "aws_lb_listener" "app_https" {
  for_each          = var.env_configs
  load_balancer_arn = aws_lb.app[each.key].arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = aws_acm_certificate_validation.app[each.key].certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[each.key].arn
  }
}

# --- Secrets & IAM ---
resource "aws_secretsmanager_secret" "db_conn" {
  for_each = var.env_configs
  name     = "myapp/db-conn-${each.key}"
}

resource "aws_secretsmanager_secret_version" "db_conn" {
  for_each      = var.env_configs
  secret_id     = aws_secretsmanager_secret.db_conn[each.key].id
  secret_string = each.value.encrypted_db_connection_string
}

resource "aws_iam_role" "app_service" {
  for_each = var.env_configs
  name     = "myapp-service-${each.key}"
  assume_role_policy = each.value.iam_mode == "programmatic" ? jsonencode({
    Version = "2012-10-17"
    Statement = [{ Effect = "Allow", Principal = { AWS = "arn:aws:iam::123456789012:root" }, Action = "sts:AssumeRole" }]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Federated = "arn:aws:iam::123456789012:oidc-provider/token.actions.githubusercontent.com" }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = { StringEquals = { "token.actions.githubusercontent.com:sub" = "repo:org/repo:ref:refs/heads/main" } }
    }]
  })
}
```

### 2. Root Configuration (`main.tf`)

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = var.default_region
}

variable "default_region" { default = "us-east-1" }

module "app_infra" {
  source      = "./modules/app_infra"
  env_configs = var.environments
}
```

### 3. Environment Configs (`dev.tfvars` & `prod.tfvars`)

**`dev.tfvars`**
```hcl
environments = {
  dev = {
    region             = "us-east-1"
    subnet_ids         = ["subnet-dev-1", "subnet-dev-2"]
    cluster_node_type  = "t3.medium"
    cluster_node_count = 2
    rds_class          = "db.t3.micro"
    rds_multi_az       = false
    enable_s3_repl     = false
    repl_region        = ""
    https_type         = "internal_alb"
    iam_mode           = "programmatic"
    encrypted_db_connection_string = "ENC[AES256_GCM,...]" # SOPS/TfVault/etc.
  }
}
```

**`prod.tfvars`**
```hcl
environments = {
  prod = {
    region             = "us-east-1"
    subnet_ids         = ["subnet-prod-1", "subnet-prod-2"]
    cluster_node_type  = "t3.large"
    cluster_node_count = 4
    rds_class          = "db.t3.medium"
    rds_multi_az       = true
    enable_s3_repl     = true
    repl_region        = "us-west-2"
    https_type         = "cloudfront"
    iam_mode           = "oidc_role"
    encrypted_db_connection_string = "ENC[AES256_GCM,...]"
  }
}
```
*(Note: Deploy each environment independently by running `terraform apply -var-file=dev.tfvars` or `prod.tfvars`. The `for_each` map keys isolate state addresses.)*

### 4. Zero-Diff State Migration

If your existing state uses flat or prefix-based addresses like `aws_s3_bucket.dev`, run these commands **before** applying the new config. This rewrites the state registry without touching AWS.

```bash
# S3
terraform state mv 'aws_s3_bucket.dev' 'module.app_infra.aws_s3_bucket["dev"]'
terraform state mv 'aws_s3_bucket.prod' 'module.app_infra.aws_s3_bucket["prod"]'
terraform state mv 'aws_s3_bucket_versioning.dev' 'module.app_infra.aws_s3_bucket_versioning["dev"]'
terraform state mv 'aws_s3_bucket_versioning.prod' 'module.app_infra.aws_s3_bucket_versioning["prod"]'
terraform state mv 'aws_s3_bucket_server_side_encryption_configuration.dev' 'module.app_infra.aws_s3_bucket_server_side_encryption_configuration["dev"]'
terraform state mv 'aws_s3_bucket_server_side_encryption_configuration.prod' 'module.app_infra.aws_s3_bucket_server_side_encryption_configuration["prod"]'
terraform state mv 'aws_s3_bucket_public_access_block.dev' 'module.app_infra.aws_s3_bucket_public_access_block["dev"]'
terraform state mv 'aws_s3_bucket_public_access_block.prod' 'module.app_infra.aws_s3_bucket_public_access_block["prod"]'

# RDS
terraform state mv 'aws_db_instance.dev' 'module.app_infra.aws_db_instance["dev"]'
terraform state mv 'aws_db_instance.prod' 'module.app_infra.aws_db_instance["prod"]'

# EKS
terraform state mv 'aws_eks_cluster.dev' 'module.app_infra.aws_eks_cluster["dev"]'
terraform state mv 'aws_eks_node_group.dev' 'module.app_infra.aws_eks_node_group["dev"]'
# Repeat for prod keys...

# HTTPS / ALB
terraform state mv 'aws_lb.dev' 'module.app_infra.aws_lb["dev"]'
terraform state mv 'aws_lb_listener.dev' 'module.app_infra.aws_lb_listener["dev"]'
# Repeat for prod keys...

# Secrets & IAM
terraform state mv 'aws_secretsmanager_secret.dev' 'module.app_infra.aws_secretsmanager_secret["dev"]'
terraform state mv 'aws_secretsmanager_secret_version.dev' 'module.app_infra.aws_secretsmanager_secret_version["dev"]'
terraform state mv 'aws_iam_role.dev' 'module.app_infra.aws_iam_role["dev"]'
# Repeat for prod keys...
```

